INSERT INTO tips VALUES(1,'Código de colores eléctricos según NB 777','codigo-colores-electricos-nb-777','Electricidad',NULL,'Guía práctica para identificar conductores por su color.',unistr('El código de colores permite identificar la función de cada conductor.\u000a\u000aEs fundamental verificar la normativa vigente en cada proyecto y seguir las indicaciones del proyectista o norma aplicable.'),4,1,1,NULL,'2026-10-19 19:09:41','2026-10-21 15:26:07','2026-10-21 19:09:41');
INSERT INTO tips VALUES(2,'Cómo seleccionar tuberías PVC para desagüe','seleccionar-tuberias-pvc-desague','Plomería',NULL,'Recomendaciones para elegir el diámetro y tipo adecuado.',unistr('La selección depende del caudal, longitud y tipo de desagüe.\u000a\u000aSiempre considere las especificaciones técnicas del fabricante y las normas aplicables.'),3,1,0,NULL,'2026-10-17 19:09:41','2026-10-21 15:26:07','2026-10-21 19:09:41');
INSERT INTO tips VALUES(3,'Cómo elegir el cable adecuado según la carga','elegir-cable-segun-carga','Electricidad',NULL,'Secciones, material y calibre: así evitas recalentamiento y caídas de tensión.',unistr('Un cable con sección insuficiente se calienta, pierde aislamiento y termina fallando.\u000a\u000aPara cargas domésticas lo más común es cobre flexible o rígido de 2,5 mm² en circuitos de iluminación y 4 mm² o 6 mm² en tomas de corriente. Ante dudas, consulta con un electricista.\u000a\u000aNo conectes cargas de potencia sin calcular la carga total del circuito.'),5,1,1,NULL,'2026-10-14 19:09:41','2026-10-21 19:09:41','2026-10-21 23:55:17');
INSERT INTO tips VALUES(4,'Errores comunes al instalar tuberías PVC sanitaria','errores-comunes-instalacion-pvc-sanitaria','Plomería',NULL,'Pendientes, sin escuadrar y sin testeado: los tres fallos que más se repiten.',unistr('Los tres errores más frecuentes son dejar la tubería sin pendiente, descuadrar los empalmes y no hacer la prueba de estanqueidad antes de tapar.\u000a\u000aUsa cuñas o nivel para dar una pendiente mínima de 1 a 2 %, y sella las uniones con el solvente correspondiente dejando el tiempo de secado indicado por el fabricante.\u000a\u000aTrabaja con guantes y ventilación adecuada: los vapores de los solventes son irritantes.'),6,1,0,NULL,'2026-10-11 19:09:41','2026-10-21 19:09:41','2026-10-21 19:09:41');
INSERT INTO tips VALUES(5,'Herramientas básicas para un kit doméstico','herramientas-basicas-kit-domestico','Ferretería',NULL,'Lo mínimo indispensable para reparar y mantener tu casa.',unistr('Un buen kit doméstico incluye: destornilladores de punta plana y de estrella, alicates de corte y de punta, llave adjustable, flexómetro, martillo unipunta y un juego de llaves Allen.\u000a\u000aBuy en punta y punta plana, en medidas de 6 a 12, con mango acolchado. El flexómetro de 5 m es más cómodo que uno de 3 m dentro de un armario.\u000a\u000aInvierte en una bolsa o caja de herramientas para mantener todo ordenado.'),5,1,0,NULL,'2026-10-08 19:09:41','2026-10-21 19:09:41','2026-10-21 19:09:41');
INSERT INTO tips VALUES(6,'Clavos, tornillos y anclajes: cuál usar en cada caso','clavos-tornillos-anclajes-cual-usar','Construcción',NULL,'Fijación en madera, mampostería o metal: qué tornillo elegir.',unistr('En madera, el tornillo autoperforante es cómodo y rápido. En mampostería necesitas taladro con punta de widia o anclaje químico. En metal, tornillo metricado y roscaExtractor.\u000a\u000aEl anclaje químico es la opción más firme para cargas pesadas en concreto, pero respeta los tiempos de curado indicados por el fabricante.\u000a\u000aUn largo de tornilloadequate es más importante que el calibre: debe penetrar al menos 2,5 cm en la base.'),6,1,0,NULL,'2026-10-05 19:09:41','2026-10-21 19:09:41','2026-10-21 19:09:41');
INSERT INTO tips VALUES(7,'Seguridad eléctrica en el taller y en casa','seguridad-electrica-taller-casa','Electricidad',NULL,'Antes de tocar un enchufe: corte la energía y verifica que está muerto.',unistr('Antes de intervenir cualquier instalación, corta la energía en el tablero y verifica la ausencia de tensión con un comprobador, no solo con el interruptor.\u000a\u000aTrabaja con herramientas aisladas, con el mango seco y sinExtensions. No toques partes metálicas descubiertas.\u000a\u000aAnte cualquier duda, llama a un electricista certificado. En FERPLEC te asesoramos en materiales, pero la instalación queda a cargo del profesional.'),4,1,0,NULL,'2026-10-02 19:09:41','2026-10-21 19:09:41','2026-10-21 19:09:41');
INSERT INTO tips VALUES(8,'Mantenimiento preventivo de la instalación sanitaria','mantenimiento-preventivo-instalacion-sanitaria','Plomería',NULL,'Revisiones de 15 minutos que evitan la mayoría de las fugas.',unistr('Revisa periódicamente los empalmes visibles, las llaves de paso y los sifones. Una gotera en la base del inodoro o un sifón que gotea suelen resolverse con un ajuste simple.\u000a\u000aLimpia los desagües con métodos caseros: no uses soda cáustica, deteriora las juntas de PVC.\u000a\u000aCierra las llaves de paso cuando no las uses y revisa el tanque de la cisterna: una válvula de llenado defectuosa consume agua sin que lo notes.'),5,1,0,NULL,'2026-09-29 19:09:41','2026-10-21 19:09:41','2026-10-21 19:09:41');
