PRAGMA foreign_keys=OFF;
BEGIN TRANSACTION;
CREATE TABLE IF NOT EXISTS "migrations" ("id" integer primary key autoincrement not null, "migration" varchar not null, "batch" integer not null);
CREATE TABLE IF NOT EXISTS "users" ("id" integer primary key autoincrement not null, "name" varchar not null, "email" varchar not null, "email_verified_at" datetime, "password" varchar not null, "remember_token" varchar, "created_at" datetime, "updated_at" datetime);
CREATE TABLE IF NOT EXISTS "password_reset_tokens" ("email" varchar not null, "token" varchar not null, "created_at" datetime, primary key ("email"));
CREATE TABLE IF NOT EXISTS "sessions" ("id" varchar not null, "user_id" integer, "ip_address" varchar, "user_agent" text, "payload" text not null, "last_activity" integer not null, primary key ("id"));
CREATE TABLE IF NOT EXISTS "cache" ("key" varchar not null, "value" text not null, "expiration" integer not null, primary key ("key"));
CREATE TABLE IF NOT EXISTS "cache_locks" ("key" varchar not null, "owner" varchar not null, "expiration" integer not null, primary key ("key"));
CREATE TABLE IF NOT EXISTS "jobs" ("id" integer primary key autoincrement not null, "queue" varchar not null, "payload" text not null, "attempts" integer not null, "reserved_at" integer, "available_at" integer not null, "created_at" integer not null);
CREATE TABLE IF NOT EXISTS "job_batches" ("id" varchar not null, "name" varchar not null, "total_jobs" integer not null, "pending_jobs" integer not null, "failed_jobs" integer not null, "failed_job_ids" text not null, "options" text, "cancelled_at" integer, "created_at" integer not null, "finished_at" integer, primary key ("id"));
CREATE TABLE IF NOT EXISTS "failed_jobs" ("id" integer primary key autoincrement not null, "uuid" varchar not null, "connection" varchar not null, "queue" varchar not null, "payload" text not null, "exception" text not null, "failed_at" datetime not null default CURRENT_TIMESTAMP);
CREATE TABLE IF NOT EXISTS "categories" ("id" integer primary key autoincrement not null, "name" varchar not null, "slug" varchar not null, "description" text, "image" varchar, "parent_id" integer, "sort_order" integer not null default '0', "is_active" tinyint(1) not null default '1', "is_featured" tinyint(1) not null default '0', "created_at" datetime, "updated_at" datetime, foreign key("parent_id") references "categories"("id") on delete set null);
CREATE TABLE IF NOT EXISTS "products" ("id" integer primary key autoincrement not null, "code" varchar not null, "name" varchar not null, "slug" varchar not null, "short_description" text, "description" text, "specifications" text, "applications" text, "category_id" integer, "subcategory_id" integer, "brand" varchar, "manufacturer" varchar, "price" numeric, "unit" varchar not null default 'unidad', "stock" integer not null default '0', "min_stock" integer not null default '0', "is_active" tinyint(1) not null default '1', "is_featured" tinyint(1) not null default '0', "images" text, "variants" text, "views" integer not null default '0', "sort_order" integer not null default '0', "created_at" datetime, "updated_at" datetime, "stock_apartado" integer not null default '0', "stock_vendido" integer not null default '0', foreign key("category_id") references "categories"("id") on delete set null, foreign key("subcategory_id") references "categories"("id") on delete set null);
CREATE TABLE IF NOT EXISTS "tips" ("id" integer primary key autoincrement not null, "title" varchar not null, "slug" varchar not null, "category" varchar not null, "image" varchar, "excerpt" text, "content" text not null, "read_time" integer not null default '3', "is_published" tinyint(1) not null default '1', "is_featured" tinyint(1) not null default '0', "related_products" text, "published_at" datetime, "created_at" datetime, "updated_at" datetime);
CREATE TABLE IF NOT EXISTS "banners" ("id" integer primary key autoincrement not null, "title" varchar, "subtitle" varchar, "description" text, "image" varchar not null, "image_mobile" varchar, "button_text" varchar, "button_link" varchar, "position" varchar not null default 'home_hero', "is_active" tinyint(1) not null default '1', "sort_order" integer not null default '0', "starts_at" datetime, "ends_at" datetime, "created_at" datetime, "updated_at" datetime);
CREATE TABLE IF NOT EXISTS "settings" ("id" integer primary key autoincrement not null, "key" varchar not null, "value" text, "created_at" datetime, "updated_at" datetime);
CREATE TABLE IF NOT EXISTS "tip_comments" ("id" integer primary key autoincrement not null, "tip_id" integer not null, "name" varchar not null, "email" varchar, "content" text not null, "is_approved" tinyint(1) not null default '0', "ip" varchar, "created_at" datetime, "updated_at" datetime, foreign key("tip_id") references "tips"("id") on delete cascade);
CREATE TABLE IF NOT EXISTS "stock_movements" ("id" integer primary key autoincrement not null, "product_id" integer not null, "type" varchar not null, "quantity" integer not null, "stock_before" integer not null, "stock_after" integer not null, "reference" varchar, "notes" text, "created_at" datetime, "updated_at" datetime, "user_id" integer, "field" varchar, "previous_value" varchar, "new_value" varchar, foreign key("product_id") references "products"("id") on delete cascade on update no action, foreign key("user_id") references "users"("id") on delete set null);
PRAGMA writable_schema=ON;
CREATE TABLE IF NOT EXISTS sqlite_sequence(name,seq);
DELETE FROM sqlite_sequence;
CREATE UNIQUE INDEX "users_email_unique" on "users" ("email");
CREATE INDEX "sessions_user_id_index" on "sessions" ("user_id");
CREATE INDEX "sessions_last_activity_index" on "sessions" ("last_activity");
CREATE INDEX "cache_expiration_index" on "cache" ("expiration");
CREATE INDEX "cache_locks_expiration_index" on "cache_locks" ("expiration");
CREATE INDEX "jobs_queue_index" on "jobs" ("queue");
CREATE INDEX "failed_jobs_connection_queue_failed_at_index" on "failed_jobs" ("connection", "queue", "failed_at");
CREATE UNIQUE INDEX "failed_jobs_uuid_unique" on "failed_jobs" ("uuid");
CREATE UNIQUE INDEX "categories_slug_unique" on "categories" ("slug");
CREATE UNIQUE INDEX "products_code_unique" on "products" ("code");
CREATE UNIQUE INDEX "products_slug_unique" on "products" ("slug");
CREATE UNIQUE INDEX "tips_slug_unique" on "tips" ("slug");
CREATE UNIQUE INDEX "settings_key_unique" on "settings" ("key");
PRAGMA writable_schema=OFF;
COMMIT;
